import{_ as t,o,c as a,a5 as r}from"./chunks/framework.CsGesDJn.js";const A=JSON.parse('{"title":"Sequence Flow — Update Workspace Member Role","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-20-update-workspace-member-role/sequence-flow.md","filePath":"feature/agency-workspace/3-4-20-update-workspace-member-role/sequence-flow.md"}'),s={name:"feature/agency-workspace/3-4-20-update-workspace-member-role/sequence-flow.md"};function l(i,e,n,h,d,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="sequence-flow-—-update-workspace-member-role" tabindex="-1">Sequence Flow — Update Workspace Member Role <a class="header-anchor" href="#sequence-flow-—-update-workspace-member-role" aria-label="Permalink to &quot;Sequence Flow — Update Workspace Member Role&quot;">​</a></h1><p>&gt; Companion to <code>spec.md</code> (FR 3.4.20). This file lists each step as actor → action → system, in enough detail to draw the sequence diagram directly. It does not restate business rules — see <code>spec.md</code> for those. &gt; &gt; Updated: 2026-09-23.</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>Client</strong> — the MANAGER of the Workspace, changing the role.</li><li><strong>System</strong> — the application service handling the request.</li><li><strong>Database</strong> — the persistent store holding membership and user records.</li></ul><hr><h2 id="flow-a-—-change-a-member-s-role-no-manager-involvement" tabindex="-1">Flow A — Change a member&#39;s role (no MANAGER involvement) <a class="header-anchor" href="#flow-a-—-change-a-member-s-role-no-manager-involvement" aria-label="Permalink to &quot;Flow A — Change a member&#39;s role (no MANAGER involvement)&quot;">​</a></h2><ol><li>Client → System: on <code>/workspaces/:id/members</code>, choose a new role for a member in the role selector — for example CREATOR to CLIENT.</li><li>System: check the caller&#39;s role in the Workspace before handling the request — a caller who is not the Workspace MANAGER is rejected with 403 <code>FORBIDDEN</code>.</li><li>System → Database: look up the member; a member that does not exist, is not active, or belongs to another Workspace is rejected with 404 <code>NOT_FOUND</code>.</li><li>System: apply the guards — the last-MANAGER guard does not trigger because the current role is not MANAGER, and the duplicate-MANAGER guard does not trigger because the new role is not MANAGER.</li><li>System: store the new role on the membership and record the update timestamp.</li><li>System → Database: write the updated membership and read the member&#39;s user record to build the response.</li><li>System → Client: the updated member entry carrying the new role.</li><li>Client: refresh the role shown for that member.</li></ol><h2 id="flow-b-—-demote-the-only-manager-blocked" tabindex="-1">Flow B — Demote the only MANAGER (blocked) <a class="header-anchor" href="#flow-b-—-demote-the-only-manager-blocked" aria-label="Permalink to &quot;Flow B — Demote the only MANAGER (blocked)&quot;">​</a></h2><ol><li>Client → System: change the role of the only MANAGER to CREATOR.</li><li>System: the caller holds the MANAGER role, so the role check passes.</li><li>System → Database: look up the member — it exists and is active.</li><li>System: the current role is MANAGER and the new role is not MANAGER, so the last-MANAGER guard runs — it counts the Workspace&#39;s active MANAGERs and blocks the change when the count is one or fewer.</li><li>System → Client: the change is rejected with 409 <code>LAST_MANAGER_CANNOT_BE_REMOVED</code>; no update is applied.</li><li>Client: show the error and ask the MANAGER to hand the role over to someone else first.</li></ol><h2 id="flow-c-—-promote-to-manager-while-another-manager-exists-blocked" tabindex="-1">Flow C — Promote to MANAGER while another MANAGER exists (blocked) <a class="header-anchor" href="#flow-c-—-promote-to-manager-while-another-manager-exists-blocked" aria-label="Permalink to &quot;Flow C — Promote to MANAGER while another MANAGER exists (blocked)&quot;">​</a></h2><ol><li>Client → System: change a member who is currently CREATOR to MANAGER, while the Workspace already has another active MANAGER.</li><li>System → Database: look up the member — it exists, is active, and currently holds CREATOR.</li><li>System: the current role is not MANAGER, so the last-MANAGER guard does not run.</li><li>System: the new role is MANAGER and the current role is not, so the duplicate-MANAGER guard runs — it counts the Workspace&#39;s active MANAGERs and blocks the change when the count is above zero.</li><li>System → Client: the change is rejected with 409 <code>MANAGER_ALREADY_ASSIGNED</code>; no update is applied.</li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>Status</th><th>Error code</th></tr></thead><tbody><tr><td>Update role</td><td>Caller is not the MANAGER of the Workspace</td><td>403</td><td><code>FORBIDDEN</code></td></tr><tr><td>Update role</td><td>Member does not exist, is not active, or belongs to another Workspace</td><td>404</td><td><code>NOT_FOUND</code></td></tr><tr><td>Update role</td><td>Member is the only MANAGER and the new role is not MANAGER</td><td>409</td><td><code>LAST_MANAGER_CANNOT_BE_REMOVED</code></td></tr><tr><td>Update role</td><td>New role is MANAGER while the Workspace already has another active MANAGER</td><td>409</td><td><code>MANAGER_ALREADY_ASSIGNED</code></td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>The last-MANAGER guard is shared with FR 3.4.16 Leave Workspace and FR 3.4.21 Remove Workspace Member, and the MANAGER count is shared with the invite and assign paths of FR 3.4.19 — so every path keeps the Workspace at exactly one active MANAGER.</li><li>There is no exception for a MANAGER acting on their own membership; the same guards apply.</li><li>A role change affects only the current Workspace.</li></ul>',16)])])}const p=t(s,[["render",l]]);export{A as __pageData,p as default};
